mapper.select:
SELECT AA.* ,CASE WHEN to_date(AA.actual_date || ' ' || AA.actual_in_time, 'DD/MM/YYYY HH24:MI') >= to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') + INTERVAL '-5' MINUTE THEN 'Y' ELSE 'N' END AS illegal_in_time_flag ,CASE WHEN AA.actual_shift_code LIKE '1%' THEN ( CASE WHEN to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') < to_date(AA.actual_date || ' 17:00', 'DD/MM/YYYY HH24:MI') AND to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') >= to_date(AA.actual_date || ' 08:00', 'DD/MM/YYYY HH24:MI') THEN ( CASE WHEN to_date(AA.actual_date || ' ' || AA.actual_out_time, 'DD/MM/YYYY HH24:MI') <= to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') + INTERVAL '9' HOUR THEN 'Y' ELSE 'N' END ) -- 1부제 Day ELSE ( CASE WHEN to_date(AA.actual_date || ' ' || AA.actual_out_time, 'DD/MM/YYYY HH24:MI') + INTERVAL '24' HOUR <= to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') + INTERVAL '9' HOUR THEN 'Y' ELSE 'N' END ) -- 1부제 Night END ) ELSE ( CASE WHEN to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') < to_date(AA.actual_date || ' 20:00', 'DD/MM/YYYY HH24:MI') AND to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') >= to_date(AA.actual_date || ' 08:00', 'DD/MM/YYYY HH24:MI') THEN ( CASE WHEN to_date(AA.actual_date || ' ' || AA.actual_out_time, 'DD/MM/YYYY HH24:MI') <= to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') + INTERVAL '12' HOUR THEN 'Y' ELSE 'N' END ) -- 2부제 Day ELSE ( CASE WHEN to_date(AA.actual_date || ' ' || AA.actual_out_time, 'DD/MM/YYYY HH24:MI') + INTERVAL '24' HOUR <= to_date(AA.actual_date || ' ' || AA.actual_start_tm, 'DD/MM/YYYY HH24:MI') + INTERVAL '12' HOUR THEN 'Y' ELSE 'N' END ) -- 2부제 Night END ) END AS illegal_out_time_flag ,'N' AS is_edit_ot ,AA.attendance_days AS attend_days FROM ( SELECT em.employee_number AS employee_no ,em.full_name_local AS employee_name ,em.grade_title AS employee_grade ,'OLD' AS data_old_new_type ,ar.shift_type_code AS actual_shift_code ,to_char(ar.time_and_attendance_date, 'dd/mm/yyyy') AS actual_date ,ac.time_and_attendance_type_code AS actual_attendance_type ,ar.time_and_attendance_code AS actual_attendance_detail ,ar.time_attend_detail_code AS actual_attend_detail_reason ,ar.night_shift_flag AS actual_day_night ,nvl(ar.evening_meal_flag, 'N') AS actual_dinner_chk ,ar.work_start_time AS actual_start_tm ,to_char(lgvatt_common_pkg.get_idcard_inout_time(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,em.employee_number ,trunc(to_date(#{attDate}, 'dd/mm/yyyy')) ,'IN'), 'HH24:MI') AS actual_in_time ,to_char(lgvatt_common_pkg.get_idcard_inout_time(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,em.employee_number ,trunc(to_date(#{attDate}, 'dd/mm/yyyy')) ,'OUT'), 'HH24:MI') AS actual_out_time ,nvl(ar.overtime_sum_hours, 0) AS actual_o_t ,lgvatt_ot_calculation_pkg.get_ot_total(ar.subsidiary_code, ar.employee_no, ar.time_and_attendance_date, ar.time_and_attendance_date, 'month_total_ot_yyyymm') AS month_total_overtime ,(CASE WHEN ar.shift_type_code IN ('2A','2B') THEN '0' ELSE lgvatt_ot_level_pkg.get_ot_level(ar.subsidiary_code, ar.employee_no, ar.time_and_attendance_yyyymm, 'request_lower_limit') END ) as overtime_limit ,nvl(ar.weekday_overtime_hours, 0) AS weekday ,nvl(ar.holiday_overtime_hours, 0) AS weekday_holiday ,nvl(ar.public_holiday_overtime_hours, 0) AS public_holiday ,nvl(ar.weekday_night_overtime_hours, 0) AS at_night_weekday ,nvl(ar.weekday_ot_af_night_work_hours, 0) AS at_night_weekday_after_o_t ,nvl(ar.holiday_night_overtime_hours, 0) AS at_night_weekday_holiday ,nvl(ar.public_holiday_night_ot_hours, 0) AS at_night_public_holiday ,nvl(ar.normal_night_overtime_hours, 0) AS night_normal ,nvl(ar.tardy_hours, 0) AS deduction_lateness ,nvl(ar.early_leave_hours, 0) AS deduction_leaving_early ,nvl(ar.going_out_hours, 0) AS deduction_going_out ,nvl(ar.special_bonus_hours, 0) AS special_bonus ,nvl(ar.helpcall_support_hours, 0) AS help_call ,NULL AS modification_reason ,ac.update_enable_flag AS actual_update_enable ,NULL AS actual_holiday_flag ,lgvatt_common_pkg.get_unit_requestor( #{LGVHR_PROJECT_SESSION.subsidiaryCode} ,#{orgName} ) AS org_get_arm_info ,ac.attendance_days FROM tb_att_result_n ar ,emp_master em ,tb_att_code_c ac WHERE 1 = 1 AND ar.employee_no = em.employee_number AND ar.time_and_attendance_code = ac.time_and_attendance_code AND ar.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} -- AND em.assignment_category = 'LGD_LW' AND em.organization_id = #{orgName} AND ar.time_and_attendance_date = trunc(to_date(#{attDate}, 'dd/mm/yyyy')) AND em.flsa_yn = 'N' AND em.fse_yn = 'N' AND ar.employee_no NOT IN (SELECT aurn.employee_no FROM tb_att_update_req_n aurn ,emp_master emp WHERE 1 = 1 AND aurn.employee_no = emp.employee_number AND emp.organization_id = #{orgName} AND aurn.time_and_attendance_date = trunc(to_date(#{attDate}, 'dd/mm/yyyy')) AND aurn.progress_status_code IN ('20', '30') AND aurn.data_old_new_type_code = 'NEW')
AND ar.shift_type_code = #{shiftCode}
AND em.employee_number like '%' || UPPER(#{employeeNo})
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
UNION ALL
SELECT em.employee_number AS employee_no ,em.full_name_local AS employee_name ,em.grade_title AS employee_grade ,'NEW' AS data_old_new_type ,ar.shift_type_code AS actual_shift_code ,to_char(ar.time_and_attendance_date, 'dd/mm/yyyy') AS actual_date ,ac.time_and_attendance_type_code AS actual_attendance_type ,ar.time_and_attendance_code AS actual_attendance_detail ,ar.time_attend_detail_code AS actual_attend_detail_reason ,ar.night_shift_flag AS actual_day_night ,nvl(ar.evening_meal_flag, 'N') AS actual_dinner_chk ,COALESCE((select distinct fl.work_start_time from tb_att_flexible_result_n fl where fl.PROGRESS_STATUS_CODE = '40' AND fl.employee_no = ar.employee_no and fl.time_and_attendance_date = ar.time_and_attendance_date), ar.work_start_time ) AS actual_start_tm ,to_char(lgvatt_common_pkg.get_idcard_inout_time(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,em.employee_number ,trunc(to_date(#{attDate}, 'dd/mm/yyyy')) ,'IN'), 'HH24:MI') AS actual_in_time ,to_char(lgvatt_common_pkg.get_idcard_inout_time(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,em.employee_number ,trunc(to_date(#{attDate}, 'dd/mm/yyyy')) ,'OUT'), 'HH24:MI') AS actual_out_time ,nvl(ar.overtime_sum_hours, 0) AS actual_o_t ,lgvatt_ot_calculation_pkg.get_ot_total(ar.subsidiary_code, ar.employee_no, ar.time_and_attendance_date, ar.time_and_attendance_date, 'month_total_ot_yyyymm') AS month_total_overtime ,(CASE WHEN ar.shift_type_code IN ('2A','2B') THEN '0' ELSE lgvatt_ot_level_pkg.get_ot_level(ar.subsidiary_code, ar.employee_no, ar.time_and_attendance_yyyymm, 'request_lower_limit') END ) as overtime_limit ,nvl(ar.weekday_overtime_hours, 0) AS weekday ,nvl(ar.holiday_overtime_hours, 0) AS weekday_holiday ,nvl(ar.public_holiday_overtime_hours, 0) AS public_holiday ,nvl(ar.weekday_night_overtime_hours, 0) AS at_night_weekday ,nvl(ar.weekday_ot_af_night_work_hours, 0) AS at_night_weekday_after_o_t ,nvl(ar.holiday_night_overtime_hours, 0) AS at_night_weekday_holiday ,nvl(ar.public_holiday_night_ot_hours, 0) AS at_night_public_holiday ,nvl(ar.normal_night_overtime_hours, 0) AS night_normal ,nvl(ar.tardy_hours, 0) AS deduction_lateness ,nvl(ar.early_leave_hours, 0) AS deduction_leaving_early ,nvl(ar.going_out_hours, 0) AS deduction_going_out ,nvl(ar.special_bonus_hours, 0) AS special_bonus ,nvl(ar.helpcall_support_hours, 0) AS help_call ,NULL AS modification_reason ,ac.update_enable_flag AS actual_update_enable ,(CASE WHEN EXISTS (select 1 from tb_att_flexible_result_n fl where fl.PROGRESS_STATUS_CODE = '40' AND fl.employee_no = ar.employee_no and fl.time_and_attendance_date = ar.time_and_attendance_date) then 'X' WHEN ar.shift_type_code IN ('2A','2B') THEN 'T' -- HMS_20260601 Add 2A,2B Shift ELSE lgvatt_common_pkg.get_holiday_flag(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,ar.shift_type_code ,trunc(to_date(#{attDate}, 'dd/mm/yyyy'))) END) AS actual_holiday_flag ,NULL AS org_get_arm_info ,ac.attendance_days FROM tb_att_result_n ar ,emp_master em ,tb_att_code_c ac WHERE 1 = 1 AND ar.employee_no = em.employee_number AND ar.time_and_attendance_code = ac.time_and_attendance_code AND ar.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} -- AND em.assignment_category = 'LGD_LW' AND em.organization_id = #{orgName} AND ar.time_and_attendance_date = trunc(to_date(#{attDate}, 'dd/mm/yyyy')) AND em.flsa_yn = 'N' AND em.fse_yn = 'N' AND ar.employee_no NOT IN (SELECT aurn.employee_no FROM tb_att_update_req_n aurn ,emp_master emp WHERE 1 = 1 AND aurn.employee_no = emp.employee_number AND emp.organization_id = #{orgName} AND aurn.time_and_attendance_date = trunc(to_date(#{attDate}, 'dd/mm/yyyy')) AND aurn.progress_status_code IN ('20', '30') AND aurn.data_old_new_type_code = 'NEW')
AND ar.shift_type_code = #{shiftCode}
AND em.employee_number like '%' || UPPER(#{employeeNo})
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
) AA ORDER BY AA.employee_grade, AA.employee_no, AA.data_old_new_type DESC

mapper.delete:
DELETE FROM tb_att_update_req_n
 WHERE 1 = 1
   AND employee_no = #{employeeNo}
   AND time_and_attendance_date = trunc(to_date(#{actualDate}, 'dd/mm/yyyy'))
   AND subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}

mapper.insert:
		INSERT INTO tb_att_update_req_n
		  (request_no
		  ,request_seq_no
		  ,request_date
		  ,subsidiary_code
		  ,time_and_attendance_date
		  ,employee_no
		  ,shift_type_code
		  ,time_and_attendance_code
		  ,work_hours
		  ,work_start_time
		  ,night_shift_flag
		  ,evening_meal_flag
		  ,overtime_sum_hours
		  ,weekday_overtime_hours
		  ,holiday_overtime_hours
		  ,public_holiday_overtime_hours
		  ,weekday_night_overtime_hours
		  ,weekday_ot_af_night_work_hours
		  ,holiday_night_overtime_hours
		  ,public_holiday_night_ot_hours
		  ,normal_night_overtime_hours
		  ,tardy_hours
		  ,early_leave_hours
		  ,going_out_hours
		  ,special_bonus_hours
		  ,helpcall_support_hours
		  ,data_old_new_type_code
		  ,update_request_reason_desc
		  ,approval_request_id
		  ,request_code
		  ,progress_status_code
		  ,time_attend_detail_code
		  ,creation_user_id
		  ,creation_date
		  ,last_update_user_id
		  ,last_update_date)
		VALUES
		  (#{requestNo}
		  ,sq_tb_att_update_req_id.nextval
		  ,SYSDATE
		  ,#{LGVHR_PROJECT_SESSION.subsidiaryCode}
		  ,trunc(to_date(#{actualDate}, 'dd/mm/yyyy'))
		  ,#{employeeNo}
		  ,#{actualShiftCode}
		  ,#{actualAttendanceDetail}
		  ,(SELECT CASE WHEN attendance_days = 1 
                        THEN CASE WHEN #{actualShiftCode} LIKE '3%' THEN 9.5 
                        ELSE lgvpay_info_pkg.get_type_work_hours(subsidiary_code,trunc(to_date(#{actualDate}, 'dd/mm/yyyy')),'21','1A',8,'perfect_work_hours') END /*HMT_20210323*/
                        WHEN attendance_days = 0.5
                        THEN CASE WHEN #{actualShiftCode} LIKE '3%' THEN 4 
                        ELSE lgvpay_info_pkg.get_type_work_hours(subsidiary_code,trunc(to_date(#{actualDate}, 'dd/mm/yyyy')),'21','1A',8,'perfect_work_hours')/2 END /*HMT_20210323*/
                        ELSE 0
                        END 
            FROM   tb_att_code_c
            WHERE  subsidiary_code          = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
            AND    time_and_attendance_code = #{actualAttendanceDetail})
		  ,#{actualStartTm}
		  ,#{actualDayNight}
		  ,#{actualDinnerChk}
		  ,#{actualOT}
		  ,#{weekday}
          ,#{weekdayHoliday}
          ,#{publicHoliday}
          ,#{atNightWeekday}
          ,#{atNightWeekdayAfterOT}
          ,#{atNightWeekdayHoliday}
          ,#{atNightPublicHoliday}
          ,#{nightNormal}
          ,#{deductionLateness}
          ,#{deductionLeavingEarly}
          ,#{deductionGoingOut}
          ,#{specialBonus}
		  ,#{helpCall}
		  ,'NEW'
		  ,#{modificationReason}
		  ,#{requestMasterId}
		  ,#{requestCode}
		  ,'20'
		  ,#{actualAttendDetailReason}
		  ,#{applicationUserId}
		  ,SYSDATE
		  ,#{applicationUserId}
		  ,SYSDATE)

mapper.update:
		UPDATE tb_att_update_req_n


           SET progress_status_code = '30'


           SET progress_status_code = '40'


           SET progress_status_code = '50'


           SET progress_status_code = '70'


           SET progress_status_code = '20'


		      ,last_update_user_id  = #{sessionAppUserId}
		      ,last_update_date     = SYSDATE
		 WHERE 1 = 1
		   AND approval_request_id = #{requestMasterId}
		   AND request_code = #{requestCode}
		   AND subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
